    VALIDATION_STATE_SUCCESS = 'VALIDATION_STATE_SUCCESS',
    TO_SUPPLY = 'TO_SUPPLY',
    IN_SALE = 'IN_SALE',
    REMOVED_FROM_SALE = 'REMOVED_FROM_SALE',
    OVERPRICED = 'OVERPRICED',
