/**
 * object
 * Список складов для расчёта товарных тегов.
 */
export interface GetSupplyOrderBundleRequestItemTagsCalculation {
    /** Идентификатор склада отгрузки поставки. */
    dropoff_warehouse_id: string;
    /** Список идентификаторов складов поставки, не больше 25 значений. */
    storage_warehouse_ids: string[];
}

/**
 * Сортировка по параметрам:
 * - `SKU` — SKU;
 * - `NAME` — названию товара;
 * - `QUANTITY` — количеству;
 * - `TOTAL_VOLUME_IN_LITRES` — объёму в литрах.
 */
export enum V1ItemSortField {
    SKU = 'SKU',
    NAME = 'NAME',
    QUANTITY = 'QUANTITY',
    TOTAL_VOLUME_IN_LITRES = 'TOTAL_VOLUME_IN_LITRES',
}

export interface V1GetSupplyOrderBundleRequest {
    /**
     * Идентификаторы товарного состава поставки. Можно получить в методе [/v3/supply-order/get](#operation/SupplyOrderGet).
     * @maxItems 100
     * @minItems 1
     */
    bundle_ids: string[];
    /** `true`, чтобы сортировать по возрастанию. */
    is_asc?: boolean;
    /** Список складов для расчёта товарных тегов. */
    item_tags_calculation?: GetSupplyOrderBundleRequestItemTagsCalculation;
    /** Идентификатор последнего значения SKU на странице. */
    last_id?: string;
    /**
     * Количество товаров на странице.
     * @format int32
     * @min 1
     * @max 100
     */
    limit: number;
    /** Поисковый запрос, например: по названию, артикулу или SKU. */
    query?: string;
    /**
     * Сортировка по параметрам:
     * - `SKU` — SKU;
     * - `NAME` — названию товара;
     * - `QUANTITY` — количеству;
     * - `TOTAL_VOLUME_IN_LITRES` — объёму в литрах.
     */
    sort_field?: V1ItemSortField;
}

/**
 * string
 * Метка Super-товара:
 * - `ITEM_SFBO_ATTRIBUTE_NONE` — без метки;
 * - `ITEM_SFBO_ATTRIBUTE_SUPER_FBO` — Super-товар;
 * - `ITEM_SFBO_ATTRIBUTE_ANTI_FBO` — неходовой товар.
 * @default "ITEM_SFBO_ATTRIBUTE_UNSPECIFIED"
 */
export enum V1ItemSfboAttribute {
    ITEM_SFBO_ATTRIBUTE_NONE = 'ITEM_SFBO_ATTRIBUTE_NONE',
    ITEM_SFBO_ATTRIBUTE_SUPER_FBO = 'ITEM_SFBO_ATTRIBUTE_SUPER_FBO',
    ITEM_SFBO_ATTRIBUTE_ANTI_FBO = 'ITEM_SFBO_ATTRIBUTE_ANTI_FBO',
}

/**
 * string
 * Тип упаковки:
 * - `BUNDLE_ITEM_SHIPMENT_TYPE_GENERAL` — обычный товар;
 * - `BUNDLE_ITEM_SHIPMENT_TYPE_BOX` — коробка;
 * - `BUNDLE_ITEM_SHIPMENT_TYPE_PALLET` — палета.
 * @default "BUNDLE_ITEM_SHIPMENT_TYPE_UNSPECIFIED"
 */
export enum V1BundleItemShipmentType {
    BUNDLE_ITEM_SHIPMENT_TYPE_GENERAL = 'BUNDLE_ITEM_SHIPMENT_TYPE_GENERAL',
    BUNDLE_ITEM_SHIPMENT_TYPE_BOX = 'BUNDLE_ITEM_SHIPMENT_TYPE_BOX',
    BUNDLE_ITEM_SHIPMENT_TYPE_PALLET = 'BUNDLE_ITEM_SHIPMENT_TYPE_PALLET',
}

