    ORDER_CREATION_NOT_AVAILABLE_FOR_SELLER = 'ORDER_CREATION_NOT_AVAILABLE_FOR_SELLER',
    ALL_ITEMS_REJECTED = 'ALL_ITEMS_REJECTED',
    NOT_AVAILABLE_CLUSTERS = 'NOT_AVAILABLE_CLUSTERS',
    ALL_ITEMS_COUNT_INVALID = 'ALL_ITEMS_COUNT_INVALID',
