export interface V1ItemsValidation {
    /**
     * Причина ошибки:
     * - `ITEM_REJECTION_REASON_OUT_OF_ASSORTMENT` — товар не входит в ассортимент;
     * - `ITEM_REJECTION_REASON_INVALID` — недействительный товар;
     * - `ITEM_REJECTION_REASON_INCOMPATIBLE_WAREHOUSE` — товар нельзя разместить на выбранном складе;
     * - `ITEM_REJECTION_REASON_EMPTY_BARCODE` — нет штрихкода;
     * - `ITEM_REJECTION_REASON_EMPTY_PS_ATTRIBUTE` — нет обязательного атрибута товара;
     * - `ITEM_REJECTION_REASON_MULTIPLICITY` — количество товара в поставке не кратно продаваемым партиям;
     * - `ITEM_REJECTION_REASON_NO_PRICE` — нет цены;
     * - `ITEM_REJECTION_REASON_INVALID_ITEM_COUNT_MAX` — количество товара больше максимального;
     * - `ITEM_REJECTION_REASON_INVALID_ITEM_COUNT_ZERO` — количество товара равно нулю;
     * - `ITEM_REJECTION_REASON_INCOMPATIBLE_SHIPMENT_TYPE` — тип отгрузки несовместим с товаром;
     * - `ITEM_REJECTION_REASON_ECONOM_QUANT_IS_NOT_FROZEN` — количество товара в эконом упаковке не фиксировано;
     * - `ITEM_REJECTION_REASON_QUANTITY_NOT_MULTIPLE_BY_QUANT` — количество товара не кратно упаковке;
     * - `ITEM_REJECTION_REASON_INVALID_QUANT_VALUE` — некорректное значение количества товара в упаковке;
     * - `ITEM_REJECTION_REASON_JEWELRY_FORBIDDEN_FOR_ECONOM` — ювелирные изделия запрещены для эконом отгрузки;
     * - `ITEM_REJECTION_REASON_NON_UNIQUE_ECONOM_ITEM_IN_REQUEST` — дублирующийся товар в эконом отгрузке в запросе;
     * - `ITEM_REJECTION_REASON_NON_UNIQUE_ECONOM_ITEM_IN_DESTINATION_BUNDLE` — дублирующийся товар в эконом отгрузке;
     * - `ITEM_REJECTION_REASON_SKU_REJECTED_BY_ACCEPTANCE_RESTRICTIONS` — товар отклонён из-за ограничений на приёмку;
     * - `ITEM_REJECTION_REASON_SKU_WITH_ETTN_REQUIRED_TAG_NOT_ALLOWED` — товар с меткой `is_ettn_required` не разрешён;
     * - `ITEM_REJECTION_REASON_SKU_WITHOUT_ETTN_REQUIRED_TAG_NOT_ALLOWED` — товар без метки `is_ettn_required` не разрешён;
     * - `ITEM_REJECTION_REASON_SKU_WITH_TRACEABLE_TAG_NOT_ALLOWED` — товар с тегом отслеживаемости не разрешён;
     * - `ITEM_REJECTION_REASON_SKU_IS_RESTRICTED` — товар ограничен к приёмке;
     * - `ITEM_REJECTION_REASON_EMPTY_CLUSTER` — нет кластера;
     * - `ITEM_REJECTION_REASON_SKU_WITH_UTD_REQUIRED_TAG_NOT_ALLOWED` — товар с обязательным тегом UTD не разрешён;
     * - `ITEM_REJECTION_REASON_STORAGE_BELARUS_SKU_HAS_NO_ANY_FEACN` — у товара для хранения в Беларуси нет кода ТН ВЭД;
     * - `ITEM_REJECTION_REASON_STORAGE_BELARUS_SKU_HAS_NO_SELLER_FEACN` — у товара для хранения в Беларуси нет кода ТН ВЭД продавца;
     * - `ITEM_REJECTION_REASON_TRACEABLE_SKU_HAS_NO_GTIN_BARCODE` — у товара нет штрихкода GTIN;
     * - `ITEM_REJECTION_REASON_TRACEABLE_SKU_HAS_NO_MEASUREMENT_UNIT_QUANTITY` — у товара нет указанного количества в единицах.
     */
    reasons?: string[];
    /**
     * Идентификатор товара в системе Ozon — SKU.
     * @format int64
     */
    sku?: number;
}

export interface V1CalculationError {
    /**
     * Возможные ошибки:
     * - `vdc_is_not_supported` — не поддерживается тип поставки вРЦ;
     * - `drop_off_point_warehouse_is_required` — не передано значение `drop_off_point_warehouse_id`;
     * - `empty_items_list` — передан пустой список `items`;
     * - `items_count_more_than_max` — превышено количество `sku`;
     * - `invalid_shipment_type` — неверный тип черновика;
     * - `unknown_cluster_ids` — кластер с таким `id` не существует;
     * - `items_validation` — ошибки валидации товарного состава;
     * - `drop_off_point_does_not_exist` — точка отгрузки с таким `id` не существует;
     * - `drop_off_point_has_no_timeslots` — нет доступных таймслотов на точке отгрузки;
     * - `total_volume_in_litres_invalid` — объём поставляемых товаров слишком большой для этой точки;
     * - `xdock_in_delivery_point_disabled_for_seller` — поставка кросс-докингом через пункт выдачи заказов недоступна для продавца.
     */
    error_message?: string;
    /** Ошибки валидации. */
    items_validation?: V1ItemsValidation[];
    /** Неизвестные идентификаторы кластеров. */
    unknown_cluster_ids?: string[];
}

/**
 * Статус создания черновика заявки на поставку:
 * - `CALCULATION_STATUS_FAILED` — не удалось создать черновик,
 * - `CALCULATION_STATUS_SUCCESS` — черновик создан,
 * - `CALCULATION_STATUS_IN_PROGRESS` — черновик создаётся,
 * - `CALCULATION_STATUS_EXPIRED` — истёк срок действия черновика.
 * @default "CALCULATION_STATUS_FAILED"
 */
export enum V1CalculationStatus {
    CALCULATION_STATUS_FAILED = 'CALCULATION_STATUS_FAILED',
    CALCULATION_STATUS_SUCCESS = 'CALCULATION_STATUS_SUCCESS',
    CALCULATION_STATUS_IN_PROGRESS = 'CALCULATION_STATUS_IN_PROGRESS',
    CALCULATION_STATUS_EXPIRED = 'CALCULATION_STATUS_EXPIRED',
}

