/**
 * Статус отмены заявки на поставку. Возможные значения:
 * - `SUCCESS` — заявка отменена.
 * - `IN_PROGRESS` — заявки в процессе отмены.
 * - `ERROR` — ошибка.
 */
export enum V1SupplyOrderCancelStatusResponseStatus {
    SUCCESS = 'SUCCESS',
    IN_PROGRESS = 'IN_PROGRESS',
    ERROR = 'ERROR',
}

export interface V1SupplyOrderCancelStatusResponse {
    /**
     * Причина, по которой не удалось отменить заявку на поставку:
     *   - `INVALID_ORDER_STATE` — неверный статус заявки на поставку.
     *   - `ORDER_IS_VIRTUAL` — заявка виртуальная.
     *   - `ORDER_DOES_NOT_BELONG_TO_CONTRACTOR` —  заявка на поставку не принадлежит вашему юридическому лицу.
     *   - `ORDER_DOES_NOT_BELONG_TO_COMPANY` — заявка на поставку не принадлежит продавцу.
     *   - `OTHER_ASYNCHRONOUS_OPERATION_IN_PROGRESS` — заявка на поставку в процессе отмены.
     */
    error_reasons?: SupplyOrderCancelStatusResponseCancelOrderError[];
    /** Информация об отмене заявки на поставку. */
    result?: SupplyOrderCancelStatusResponseResult;
    /**
     * Статус отмены заявки на поставку. Возможные значения:
     * - `SUCCESS` — заявка отменена.
     * - `IN_PROGRESS` — заявки в процессе отмены.
     * - `ERROR` — ошибка.
     */
    status?: V1SupplyOrderCancelStatusResponseStatus;
}

export interface V1SupplyOrderContentUpdateRequestItem {
    /**
     * Размер кванта.
     * @format int32
     */
    quant: number;
    /**
     * Количество товара.
     * @format int32
     */
    quantity: number;
    /**
     * Идентификатор товара в системе Ozon — SKU.
     * @format int64
     */
    sku: number;
}

export interface V1SupplyOrderContentUpdateRequest {
    /**
     * Новый товарный состав заявки на поставку.
     *
     * Максимум 5000 товаров.
     */
    items: V1SupplyOrderContentUpdateRequestItem[];
    /**
     * Идентификатор заказа.
     * @format int64
     */
    order_id: number;
    /**
     * Идентификатор поставки.
     * @format int64
     */
    supply_id: number;
}

