/**
 * string
 * Фильтр по видимости товара:
 *   - `ALL` — все товары, кроме архивных;
 *   - `VALIDATION_STATE_FAIL` — товары, которые не прошли проверку валидатором на премодерации;
 *   - `TO_SUPPLY` — товары, готовые к продаже;
 *   - `IN_SALE` — товары в продаже;
 *   - `REMOVED_FROM_SALE` — товары, скрытые от покупателей;
 *   - `PARTIAL_APPROVED` — товары с предупреждениями, требуют доработки;
 *   - `IMAGE_ABSENT` — товары без фото;
 *   - `ARCHIVED` — товары в архиве;
 *   - `AUTO_ARCHIVED` — товары, архивированные автоматически;
 *   - `MANUAL_ARCHIVED` — товары, архивированные вручную.
 * @default "ALL"
 */
export enum ReportCreateCompanyProductsReportRequestVisibility {
    ALL = 'ALL',
    VALIDATION_STATE_FAIL = 'VALIDATION_STATE_FAIL',
    TO_SUPPLY = 'TO_SUPPLY',
    IN_SALE = 'IN_SALE',
    REMOVED_FROM_SALE = 'REMOVED_FROM_SALE',
    PARTIAL_APPROVED = 'PARTIAL_APPROVED',
    IMAGE_ABSENT = 'IMAGE_ABSENT',
    ARCHIVED = 'ARCHIVED',
    AUTO_ARCHIVED = 'AUTO_ARCHIVED',
    MANUAL_ARCHIVED = 'MANUAL_ARCHIVED',
}

