/**
 * object
 * Фильтр.
 */
export interface V2ReportReturnsCreateRequestFilter {
    /**
     * Фильтр по схеме работы:
     * - `FBS` — возвраты на свой склад.
     * - `FBO` — возвраты на склад маркетплейса.
     * - `ALL` — все возвраты.
     */
    delivery_schema?: 'FBS' | 'FBO' | 'ALL';
    /**
     * Дата, с которой данные отображаются в отчёте.
     *
     * Доступно только за последние три месяца.
     * @format date-time
     */
    date_from: string;
    /**
     * Дата, по которую данные отображаются в отчёте.
     *
     * Доступно только за последние три месяца.
     * @format date-time
     */
    date_to: string;
    /**
     * Фильтр по статусу возврата:
     * - `DisputeOpened` — открыт спор с покупателем;
     * - `OnSellerApproval` — на согласовании у продавца;
     * - `ArrivedAtReturnPlace` — в пункте выдачи;
     * - `OnSellerClarification` — на уточнении у продавца;
     * - `OnSellerClarificationAfterPartialCompensation` — на уточнении у продавца после частичной компенсации;
     * - `OfferedPartialCompensation` — предложена частичная компенсация;
     * - `ReturnMoneyApproved` — одобрен возврат денег;
     * - `PartialCompensationReturned` — вернули часть денег;
     * - `CancelledDisputeNotOpen` — возврат отклонён, спор не открыт;
     * - `Rejected` — заявка отклонена;
     * - `CrmRejected` — заявка отклонена Ozon;
     * - `Cancelled` — заявка отменена;
     * - `Approved` — заявка одобрена продавцом;
     * - `ApprovedByOzon` — заявка одобрена Ozon;
     * - `ReceivedBySeller` — продавец получил возврат;
     * - `MovingToSeller` — возврат на пути к продавцу;
     * - `ReturnCompensated` — продавец получил компенсацию;
     * - `ReturningToSellerByCourier` — курьер везёт возврат продавцу;
     * - `Utilizing` — на утилизации;
     * - `Utilized` — утилизирован;
     * - `MoneyReturned` — покупателю вернули всю сумму;
     * - `PartialCompensationInProcess` — одобрен частичный возврат денег;
     * - `DisputeYouOpened` — продавец открыл спор;
     * - `CompensationRejected` — отказано в компенсации;
     * - `DisputeOpening` — обращение в поддержку отправлено;
     * - `CompensationOffered` — ожидает вашего решения по компенсации;
     * - `WaitingCompensation` — ожидает компенсации;
     * - `SendingError` — ошибка при отправке обращения в поддержку;
     * - `CompensationRejectedBySla` — истёк срок решения;
     * - `CompensationRejectedBySeller` — продавец отказался от компенсации;
     * - `MovingToOzon` — едет на склад Ozon;
     * - `ReturnedToOzon` — на складе Ozon;
     * - `MoneyReturnedBySystem` — быстрый возврат;
     * - `WaitingShipment` — ожидает отправки.
     */
    status:
        | 'DisputeOpened'
        | 'OnSellerApproval'
        | 'ArrivedAtReturnPlace'
        | 'OnSellerClarification'
        | 'OnSellerClarificationAfterPartialCompensation'
        | 'OfferedPartialCompensation'
        | 'ReturnMoneyApproved'
        | 'PartialCompensationReturned'
        | 'CancelledDisputeNotOpen'
        | 'Rejected'
        | 'CrmRejected'
        | 'Cancelled'
        | 'Approved'
        | 'ApprovedByOzon'
        | 'ReceivedBySeller'
        | 'MovingToSeller'
        | 'ReturnCompensated'
        | 'ReturningToSellerByCourier'
        | 'Utilizing'
        | 'Utilized'
        | 'MoneyReturned'
        | 'PartialCompensationInProcess'
        | 'DisputeYouOpened'
        | 'CompensationRejected'
        | 'DisputeOpening'
        | 'CompensationOffered'
        | 'WaitingCompensation'
        | 'SendingError'
        | 'CompensationRejectedBySla'
        | 'CompensationRejectedBySeller'
        | 'MovingToOzon'
        | 'ReturnedToOzon'
        | 'MoneyReturnedBySystem'
        | 'WaitingShipment';
}

