    DELIVERY_DRIVER_NAME_LENGTH_MAXIMUM_REACHED = 'DELIVERY_DRIVER_NAME_LENGTH_MAXIMUM_REACHED',
    DELIVERY_VEHICLE_GENRE_LENGTH_MAXIMUM_REACHED = 'DELIVERY_VEHICLE_GENRE_LENGTH_MAXIMUM_REACHED',
    DELIVERY_VEHICLE_REGISTRATION_PLATE_LENGTH_MAXIMUM_REACHED = 'DELIVERY_VEHICLE_REGISTRATION_PLATE_LENGTH_MAXIMUM_REACHED',
    DELIVERY_TPL_NAME_LENGTH_MAXIMUM_REACHED = 'DELIVERY_TPL_NAME_LENGTH_MAXIMUM_REACHED',
