    DELIVERY_VEHICLE_GENRE_EMPTY = 'DELIVERY_VEHICLE_GENRE_EMPTY',
    DELIVERY_VEHICLE_REGISTRATION_PLATE_EMPTY = 'DELIVERY_VEHICLE_REGISTRATION_PLATE_EMPTY',
