    DELIVERY_BY_SELLER_EMPTY = 'DELIVERY_BY_SELLER_EMPTY',
    DELIVERY_BY_TPL_EMPTY = 'DELIVERY_BY_TPL_EMPTY',
    RECEIVE_DATE_NOT_SET = 'RECEIVE_DATE_NOT_SET',
    SUPPLY_TYPE_NOT_SUPPORTED = 'SUPPLY_TYPE_NOT_SUPPORTED',
    INVALID_BUSINESS_FLOW = 'INVALID_BUSINESS_FLOW',
    ORDER_LOCKED = 'ORDER_LOCKED',
    INVALID_TIMESLOT = 'INVALID_TIMESLOT',
    DROP_OFF_DETAILS_EMPTY = 'DROP_OFF_DETAILS_EMPTY',
