export enum FbpCreateActResponseCreateActErrorReason {
    CREATE_ACT_ERROR_REASON_UNSPECIFIED = 'CREATE_ACT_ERROR_REASON_UNSPECIFIED',
    INVALID_ORDER_TYPE = 'INVALID_ORDER_TYPE',
}

export interface V1FbpCreateActResponse {
    /**
     * Причина ошибки:
     * - `CREATE_ACT_ERROR_REASON_UNSPECIFIED` — не определена;
     * - `INVALID_ORDER_TYPE` — нельзя создать акт для указанного идентификатора поставки.
     * @default "CREATE_ACT_ERROR_REASON_UNSPECIFIED"
     */
    errors?: FbpCreateActResponseCreateActErrorReason[];
    /** Идентификатор акта приёмки. */
    file_uuid?: string;
    /** `true`, если в запросе нет ошибок. */
    is_success?: boolean;
}

export interface V1FbpCheckActStateRequest {
    /** Идентификатор акта приёмки. */
    file_uuid: string;
}

/**
 * Ошибка генерации:
 * - `ERROR_REASON_UNSPECIFIED` — не определена;
 * - `INVALID_COMPANY` — неверная компания;
 * - `FILE_NOT_FOUND` — файл не найден;
 * - `GENERATE_TIMEOUT_REACHED` — превышено время генерации;
 * - `GENERATION_ERROR` — ошибка во время генерации.
 * @default "ERROR_REASON_UNSPECIFIED"
 */
export enum FbpCheckActStateResponseErrorReason {
    ERROR_REASON_UNSPECIFIED = 'ERROR_REASON_UNSPECIFIED',
    INVALID_COMPANY = 'INVALID_COMPANY',
    FILE_NOT_FOUND = 'FILE_NOT_FOUND',
    GENERATE_TIMEOUT_REACHED = 'GENERATE_TIMEOUT_REACHED',
    GENERATION_ERROR = 'GENERATION_ERROR',
}

/**
 * Статус генерации:
 * - `STATUS_UNSPECIFIED` — не определён;
 * - `NOT_EXIST` — не существует;
 * - `PROCESSING` — в процессе;
 * - `EXIST` — завершена;
 * - `ERROR` — ошибка.
 * @default "STATUS_UNSPECIFIED"
 */
export enum V1FbpCheckActStateResponseStatus {
    STATUS_UNSPECIFIED = 'STATUS_UNSPECIFIED',
    NOT_EXIST = 'NOT_EXIST',
    PROCESSING = 'PROCESSING',
    EXIST = 'EXIST',
    ERROR = 'ERROR',
}

export interface V1FbpCheckActStateResponse {
    /** Ссылка на акт приёмки. */
    cdn_url?: string;
    /**
     * Ошибка генерации:
     * - `ERROR_REASON_UNSPECIFIED` — не определена;
     * - `INVALID_COMPANY` — неверная компания;
     * - `FILE_NOT_FOUND` — файл не найден;
     * - `GENERATE_TIMEOUT_REACHED` — превышено время генерации;
     * - `GENERATION_ERROR` — ошибка во время генерации.
     */
    error?: FbpCheckActStateResponseErrorReason;
    /**
     * Статус генерации:
     * - `STATUS_UNSPECIFIED` — не определён;
     * - `NOT_EXIST` — не существует;
     * - `PROCESSING` — в процессе;
     * - `EXIST` — завершена;
     * - `ERROR` — ошибка.
     */
    status?: V1FbpCheckActStateResponseStatus;
}

